"""Build a self-contained review page (images remain adjacent repository assets)."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
manifest=json.loads((root/'docs/art-completion/manifest.json').read_text())
data=[{k:s[k] for k in ('id','file','cols','rows','entries','transparent','width','height')} for s in manifest['sets']]
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Idlewick Art Completion Pack · review</title><style>
*{box-sizing:border-box}body{margin:0;background:#eee7d7;color:#302d26;font:16px/1.45 Georgia,serif}header,main{padding:24px;max-width:1800px;margin:auto}header{padding-bottom:12px}h1{font-size:28px;margin:0 0 8px}p{max-width:850px}button,a{font:inherit}button{border:1px solid #88764f;border-radius:6px;padding:7px 12px;color:inherit;background:transparent;cursor:pointer}button[aria-pressed=true]{background:#b28438;color:#fff}nav,.controls{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}.card{padding:12px;border:1px solid #8b806d55;border-radius:9px;min-width:0;background:#fff8}.art{display:block;width:var(--size,128px);height:var(--size,128px);margin:8px auto;background-repeat:no-repeat}.landscape .art{width:100%;height:auto;aspect-ratio:3}.landscape{grid-column:span 2}.card h3{font:600 14px/1.3 system-ui;overflow-wrap:anywhere;margin:8px 0}.card p{font:12px/1.35 system-ui;color:#726c5e;margin:0}.dark{background:#121b20;color:#e5ddca}.dark .card{background:#1c292e}.dark .card p{color:#b6b4aa}.checker .art{outline:1px solid #999}.count{font:14px system-ui;color:#756241}a{color:inherit}.dark .count{color:#bea472}footer{padding:24px}h2{font-size:21px}section{margin-bottom:28px}@media(max-width:500px){header,main{padding:14px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.art{max-width:100%;height:auto;aspect-ratio:1}.landscape{grid-column:1/-1}}
</style><header><h1>Idlewick Art Completion Pack</h1><p>Painted asset catalogue. The original pack is integrated; next-brief additions are proposed for review. Fitted hero layers await compositor integration. Review at small sizes as well as enlarged; the current hero and creature collection are unchanged.</p><nav aria-label="Asset category"></nav><div class="controls"><button id="theme" aria-pressed="false">Dark background</button><button data-size="64">64 px</button><button data-size="128" aria-pressed="true">128 px</button><button data-size="256">256 px</button><a href="manifest.json">Manifest and exact prompts</a></div><p class="count" role="status"></p></header><main></main><footer>Gouache-inspired generated raster assets. Check transparency, small-size readability, grid alignment and species/material identity before approval. See NEXT-DELIVERY.md for the integration status of the additions.</footer><script>
const sets=__DATA__;let selected='all';const nav=document.querySelector('nav'),main=document.querySelector('main');
for(const id of ['all',...sets.map(s=>s.id)]){const b=document.createElement('button');b.textContent=id==='all'?'All assets':id.replaceAll('-',' ');b.dataset.category=id;b.setAttribute('aria-pressed',id===selected);b.onclick=()=>{selected=id;render()};nav.append(b)}
function render(){main.replaceChildren();let count=0;for(const s of sets){if(selected!=='all'&&selected!==s.id)continue;const section=document.createElement('section'),heading=document.createElement('h2'),link=document.createElement('a'),grid=document.createElement('div');heading.textContent=s.id.replaceAll('-',' ')+' · '+s.entries.length;link.href='../../'+s.file;link.textContent='Open full atlas';grid.className='grid';section.append(heading,link,grid);s.entries.forEach((e,i)=>{const card=document.createElement('article'),art=document.createElement('span'),name=document.createElement('h3'),desc=document.createElement('p');card.className='card'+(!s.transparent?' landscape':'');art.className='art';art.role='img';art.setAttribute('aria-label',e.subject);art.style.backgroundImage=`url('../../${s.file}')`;const [rx,ry,rw,rh]=e.rect;art.style.backgroundSize=`${s.width/rw*100}% ${s.height/rh*100}%`;art.style.backgroundPosition=`${s.width===rw?0:rx/(s.width-rw)*100}% ${s.height===rh?0:ry/(s.height-rh)*100}%`;art.style.aspectRatio=rw+'/'+rh;art.style.height='auto';name.textContent=e.id;desc.textContent=e.subject;card.append(art,name,desc);grid.append(card);count++});main.append(section)}document.querySelector('.count').textContent=count+' proposed assets shown';nav.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===selected))}
document.getElementById('theme').onclick=e=>{const dark=document.body.classList.toggle('dark');e.target.setAttribute('aria-pressed',dark)};document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{document.documentElement.style.setProperty('--size',b.dataset.size+'px');document.querySelectorAll('[data-size]').forEach(x=>x.setAttribute('aria-pressed',x===b))});render();
</script></html>'''.replace('__DATA__',json.dumps(data).replace('</','<\\/'))
(root/'docs/art-completion/review.html').write_text(html)
print('Built docs/art-completion/review.html')
